import sys

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    k = int(input[index + 1])
    index += 2
    powers = []
    for _ in range(n):
        powers.append(list(map(int, input[index:index + k])))
        index += k

    def can_win(sportsman_index, n, k, powers):
        for opponent_index in range(n):
            if opponent_index == sportsman_index:
                continue
            can_beat = False
            for sport in range(k):
                if powers[sportsman_index][sport] > powers[opponent_index][sport]:
                    can_beat = True
                    break
            if not can_beat:
                return False
        return True

    results = []
    for i in range(1, n + 1):
        winners = 0
        for j in range(i):
            if can_win(j, i, k, powers):
                winners += 1
        results.append(winners)

    print("\n".join(map(str, results)))

if __name__ == "__main__":
    main()
